  padding-bottom: 8px;
  background: var(--g-color-base-generic);
}

.dashboard-group-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 0;
  padding: 6px 8px;
  border-radius: 8px;
  background: transparent;
  color: var(--g-color-text-primary);
  font: inherit;
  cursor: pointer;
}

.dashboard-group-toggle:hover {
  background: var(--g-color-base-generic-hover);
}

.rotated {
  transform: rotate(-90deg);
}

@media (max-width: 760px) {
  .dashboard-header {
    align-items: start;
    flex-direction: column;
  }

  .dashboard-content {
    padding: 16px;
  }
}
